using MediatR;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Exceptions;
namespace JTradeERP.Application.Features.MasterData.Customers.UpdateCustomer;
public sealed class UpdateCustomerHandler(IApplicationDbContext db):IRequestHandler<UpdateCustomerCommand,UpdateCustomerResponse>{public async Task<UpdateCustomerResponse> Handle(UpdateCustomerCommand r,CancellationToken ct){var e=db.Customers.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Customer not found.");if(db.Customers.Any(x=>x.Id!=r.Id&&x.CustomerCode==r.CustomerCode.Trim()))throw new ConflictException("Customer code already exists.");e.Update(r.CustomerCode,r.Name,r.BillingAddress,r.ShippingAddress,r.Phone,r.Email,r.TRN,r.CreditLimit);await db.SaveChangesAsync(ct);return new(e.Id,e.CustomerCode,e.Name,e.BillingAddress,e.ShippingAddress,e.Phone,e.Email,e.TRN,e.CreditLimit);}}
